"""Save an offline comparison gallery for the pair-strength experiment."""
import json
from collections import Counter,defaultdict
from datetime import datetime,timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
RUN=ROOT/'runs/pair-strength-search-20261027'
OUT=ROOT/'sites/talkie-neuron-sample/dist/strength-study'

def main():
    rows=[]
    path=RUN/'attempts.jsonl'
    for line in path.read_text().splitlines() if path.exists() else []:
        try:rows.append(json.loads(line))
        except json.JSONDecodeError:pass
    assert len({r['id'] for r in rows})==len(rows)
    parents=json.loads((RUN/'parents.json').read_text());parent_by={r['id']:r for r in parents}
    for r in rows:
        if r['kind']=='retest' and r['job'] in ['00-parent-baselines','03-additional-baselines']:
            parent_by[r['source_id']]['fresh_baseline']={'id':r['id'],'text':r['text'],'termination':r['termination']}
        r['n_tokens']=len(r.pop('token_ids',[]))
        if r['kind'] in ['pair','ablation']:
            assert len(r['parents'])==len(r['edits'])==2
            for p,e,f in zip(r['parents'],r['edits'],r['factors']):
                assert e[:3]==parent_by[p]['edits'][0][:3]
                assert abs(e[3]-parent_by[p]['edits'][0][3]*f)<1e-7
    review_path=RUN/'editorial_reviews.json'
    reviews=json.loads(review_path.read_text()) if review_path.exists() else []
    plan=json.loads((RUN/'pair_plan.json').read_text());groups=defaultdict(list)
    for r in rows:
        if r['kind'] in ['pair','ablation']:groups[r['pair_id']].append(r)
    payload={'complete':(RUN/'DONE.json').exists(),'updated':datetime.now(timezone.utc).isoformat(),
             'protocol':json.loads((RUN/'protocol.json').read_text()),'parents':parents,
             'icons':json.loads((OUT.parent/'icons/strength-index.json').read_text()) if (OUT.parent/'icons/strength-index.json').exists() else {},
             'replication':json.loads((RUN/'replication_checks.json').read_text()) if (RUN/'replication_checks.json').exists() else [],
             'pairs':[{**p,'rows':groups[p['id']]} for p in plan if groups.get(p['id'])],
             'reviews':reviews,'stats':{'pairs':len(groups),'pair_trials':sum(r['kind']=='pair' for r in rows),'single_parent_checks':sum(r['kind']=='ablation' for r in rows),'all_replies':len(rows),'controls':sum(r['kind']=='control' for r in rows),'selected':sum(r.get('selected',True) for r in reviews)},'rows':rows}
    OUT.mkdir(exist_ok=True,parents=True)
    (OUT/'results.json').write_text(json.dumps(payload,ensure_ascii=False,separators=(',',':'))+'\n')
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Strength changes · Talkie pair study</title><style>
    *{box-sizing:border-box}body{margin:0;color:#242428;background:#fff;font:16px/1.55 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:30px 28px 80px}a{color:inherit}nav,.meta,.note,summary{font-size:13px;color:#767680}nav{display:flex;justify-content:space-between;gap:20px}header{padding:55px 0 30px;border-bottom:1px solid #e4e4e9}h1{font:clamp(42px,7vw,72px)/1.08 Georgia,serif;letter-spacing:-.035em;max-width:900px;margin:0 0 24px}.intro{font-size:20px;max-width:850px;color:#65656f}.stats{display:flex;gap:45px;flex-wrap:wrap;margin:25px 0}.stats b{display:block;font-size:32px;color:#242428}.stats span{font-size:13px;color:#767680}.tools{padding:20px 0;background:white;position:sticky;top:0;z-index:2;border-bottom:1px solid #e4e4e9;display:flex;gap:12px;flex-wrap:wrap}button,input{font:inherit}button{cursor:pointer;border:1px solid #dedee4;background:white;color:#242428;border-radius:22px;padding:9px 15px}button[aria-pressed=true]{background:#242428;color:white;border-color:#242428}input{flex:1;min-width:220px;border:1px solid #dedee4;border-radius:8px;padding:10px 15px}.pair{scroll-margin-top:110px;padding:35px 0;border-bottom:1px solid #e4e4e9}.pair h2{font-size:28px;line-height:1.25;margin:10px 0 12px;letter-spacing:-.02em}.why{max-width:900px;color:#65656f}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:22px 0}.reply{padding:22px;background:#f5f5f7;border:1px solid #e5e5ea;border-radius:16px}.reply-robot{float:right;width:68px;height:auto;margin:0 0 10px 12px}.text{clear:both}.reply h3{font-size:17px;margin:0 0 15px}.text{white-space:pre-wrap;line-height:1.65}.dose{font:13px ui-monospace,monospace;color:#8b6312;margin-bottom:12px}.rating{font-size:12px;color:#767680;border-top:1px solid #dedee4;padding-top:12px;margin-top:18px}.foot{margin-top:16px;color:#898992;font-size:11px}details{margin-top:18px}summary{cursor:pointer}.parent-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.parent-grid p{white-space:pre-wrap;font-size:14px}.notice{padding:14px 18px;background:#faf7ef;border-radius:10px;color:#756b52;font-size:14px}.empty{padding:35px;color:#767680}footer{font-size:13px;color:#767680;margin-top:40px}#count{font-size:13px;color:#767680}@media(max-width:850px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:550px){main{padding:22px 16px}.grid,.parent-grid{grid-template-columns:1fr}.tools{position:static}.pair h2{font-size:24px}header{padding-top:35px}}
    </style></head><body><main><nav><a href="../">← Talkie Persona Library</a><span><a href="report.html" download>Offline report</a> · <a href="results.json" download>Full study data</a></span></nav><header><h1>Small changes in strength.<br>Different voices.</h1><p class="intro">The same two neurons, pushed by different amounts. Selected transitions show where a readable reply turns into a different, surprising character.</p><div class="stats" id="stats"></div><p class="notice">A factor such as 0.5× multiplies each parent’s own saved solo strength. Equal factors need not mean equal absolute pushes. Prompt: “Who are you?” · Greedy decoding · No persona instructions.</p><p class="note" id="status"></p></header><div class="tools"><button id="selected" aria-pressed="true">Selected transitions</button><button id="all" aria-pressed="false">Every tested pair</button><input id="search" placeholder="Search a parent, discovery, or phrase…" aria-label="Search the strength study"></div><p id="count"></p><div id="pairs"></div><button id="more">Show more pairs</button><footer><p>Exploratory model outputs. Editorial labels describe the saved replies; they do not establish stable identities or neuron functions. All failures, truncated replies and repeat-stopped replies are preserved. Selected replies were rerun in a smaller, reordered batch: 5 of 19 matched exactly and 12 of 19 matched in their first 120 characters. Changed reruns remain alongside their originals; a result is not a guaranteed persona. Initial previews: 64 tokens. Finalists: 160 tokens. Exact settings and batch IDs are included in the download.</p><details><summary>Study protocol</summary><pre id="protocol" style="white-space:pre-wrap"></pre></details></footer></main><script>
    const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data,selected=true,limit=12,parents,reviews,byid;
    function dose(r){return r.factors[0]===r.factors[1]?r.factors[0]+'× each':r.factors[0]+'× left / '+r.factors[1]+'× right'}
    function card(r,stage){return '<article class="reply">'+(data.icons[r.id]?'<img class="reply-robot" src="../'+esc(data.icons[r.id])+'" alt="" width="68" height="81">':'')+'<div class="dose">'+esc(dose(r))+' of solo strength</div>'+(stage?.label?'<h3>'+esc(stage.label)+'</h3>':'')+'<div class="text">'+esc(r.text||'[Empty reply]')+'</div>'+(stage?.coherence!=null?'<div class="rating">Weirdness '+stage.weirdness+'/10 · Coherence '+stage.coherence+'/10 · Codex</div>':'')+'<div class="foot">'+r.n_tokens+' tokens · '+esc(r.termination==='length'?'Cut off':r.termination==='repeating'?'Stopped on repetition':r.termination)+' · '+esc(r.id)+' · '+esc(r.job)+'</div></article>'}
    function render(){const q=$('search').value.trim().toLowerCase();let ps=data.pairs.filter(p=>(!selected||reviews.get(p.id)?.selected!==false&&reviews.has(p.id))&&(!q||[p.parents.map(i=>parents.get(i).name).join(' '),reviews.get(p.id)?.title,...p.rows.map(r=>r.text)].join(' ').toLowerCase().includes(q)));if(selected)ps.sort((a,b)=>(reviews.get(a.id).order??999)-(reviews.get(b.id).order??999));$('count').textContent=ps.length+' '+(selected?'selected transitions':'tested pairs');$('pairs').innerHTML=ps.slice(0,limit).map(p=>{const v=reviews.get(p.id),names=p.parents.map(i=>parents.get(i).name);let chosen=v?.stages?.map(s=>byid.get(s.id)).filter(Boolean)||p.rows.filter(r=>['01-strength-screen','04-supplemental-screen'].includes(r.job));const shown=new Set(chosen.map(r=>r.id));return '<section class="pair" id="'+p.id+'"><div class="meta">'+names.map(esc).join(' + ')+'</div><h2>'+esc(v?.title||names.join(' + '))+'</h2>'+(v?'<p class="why">'+esc(v.reason)+'</p>':'<p class="note">Saved strength sweep · not editorially selected</p>')+'<div class="grid">'+chosen.map(r=>card(r,v?.stages?.find(s=>s.id===r.id))).join('')+'</div><details><summary>Compare the two fresh solo baselines</summary><div class="parent-grid">'+p.parents.map(i=>{const a=parents.get(i);return '<div><b>'+esc(a.name)+'</b><p>'+esc(a.fresh_baseline?.text||a.text)+'</p><span class="note">'+esc(a.fresh_baseline?.id||a.id)+'</span></div>'}).join('')+'</div></details><details><summary>Every saved strength and rerun ('+p.rows.length+' trials)</summary><div class="grid">'+p.rows.filter(r=>!shown.has(r.id)).map(r=>card(r,v?.stages?.find(s=>s.id===r.id))).join('')+'</div><p class="note">Each row records the exact factors and batch. Additional digits in the full data preserve the intervention coefficients.</p></details></section>'}).join('')||'<p class="empty">'+(data.complete?'No matching pairs.':'Generation and review are in progress. Every saved pair is available in the other tab.')+'</p>';$('more').hidden=ps.length<=limit}
    LOADER.then(d=>{data=d;parents=new Map(d.parents.map(p=>[p.id,p]));reviews=new Map(d.reviews.map(r=>[r.pair_id,r]));byid=new Map(d.rows.map(r=>[r.id,r]));$('stats').innerHTML=[[d.stats.pairs,'neuron pairs'],[d.stats.pair_trials,'pair-strength trials'],[d.stats.selected,'selected transitions']].map(([v,s])=>'<div><b>'+v.toLocaleString()+'</b><span>'+s+'</span></div>').join('');$('status').textContent=(d.complete?'Study complete.':'Study in progress.')+' '+d.stats.all_replies.toLocaleString()+' saved replies, including '+d.stats.controls+' unsteered batch controls.';$('protocol').textContent=JSON.stringify(d.protocol,null,2);if(location.hash){const id=location.hash.slice(1);if(!reviews.has(id)){selected=false;$('selected').setAttribute('aria-pressed',false);$('all').setAttribute('aria-pressed',true)}limit=d.pairs.length;}render();if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView();});$('selected').onclick=()=>{selected=true;limit=12;$('selected').setAttribute('aria-pressed',true);$('all').setAttribute('aria-pressed',false);render()};$('all').onclick=()=>{selected=false;limit=12;$('selected').setAttribute('aria-pressed',false);$('all').setAttribute('aria-pressed',true);render()};$('search').oninput=()=>{limit=12;render()};$('more').onclick=()=>{limit+=12;render()};
    </script></body></html>'''
    (OUT/'index.html').write_text(html.replace('LOADER',"fetch('results.json',{cache:'no-store'}).then(r=>r.json())"))
    embedded=json.dumps(payload,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    offline=html.replace('<script>','<script type="application/json" id="saved-study">'+embedded+'</script><script>',1).replace('LOADER',"Promise.resolve(JSON.parse(document.getElementById('saved-study').textContent))")
    (OUT/'report.html').write_text(offline);(RUN/'report.html').write_text(offline)
    (RUN/'report_summary.json').write_text(json.dumps(payload['stats'],indent=2)+'\n')
    print(json.dumps(payload['stats']))

if __name__=='__main__':main()
